/** Lấy text đã dịch theo slug + field; fallback giá trị Vi gốc nếu thiếu. */
export function trField(slug: string, field: keyof ContentTrans, lang: LangCode, fallback: string): string {
  const e = CONTENT_I18N[slug];
  if (!e) return fallback;
  const f = e[field] as LangMap | undefined;
  if (!f) return fallback;
  return (f[lang] as string | undefined) ?? fallback;
}

export function trTags(slug: string, lang: LangCode, fallback: string[]): string[] {
  const e = CONTENT_I18N[slug];
  if (!e?.tags) return fallback;
  return (e.tags[lang] as string[] | undefined) ?? fallback;
}
